using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;
public static class SignalBuild{
const string Folder="Assets/Scenes/Oasis/TrafficSignals/";
[InitializeOnLoadMethod]static void Init(){EditorApplication.delayCall+=Run;}
static Vector3 Head(Vector3 p,bool vertical){var center=vertical?new Vector3(.102f,4.388f,-7.778f):new Vector3(.189f,4.837f,-3.998f);return center+(p-center)*1.35f;}
static void Run(){if(!File.Exists("SignalBuild.request"))return;File.Delete("SignalBuild.request");string path="Assets/Scenes/Oasis/3D/Prefeb/Signal.prefab";Directory.CreateDirectory("SignalBackup");if(!File.Exists("SignalBackup/Signal.prefab"))File.Copy(path,"SignalBackup/Signal.prefab");var go=PrefabUtility.LoadPrefabContents(path);try{
var mf=go.GetComponent<MeshFilter>();var q=go.transform.localRotation;var inv=Quaternion.Inverse(q);string meshpath=Folder+"Signal Enhanced.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshpath);
if(!mesh){mesh=UnityEngine.Object.Instantiate(mf.sharedMesh);mesh.name="Signal Enhanced";var v=mesh.vertices;var normals=mesh.normals;var parts=SignalAudit.Parts(mesh);foreach(var part in parts){var b=new Bounds(q*v[part[0]],Vector3.zero);foreach(int i in part)b.Encapsulate(q*v[i]);bool vert=b.center.z < -7.5f&&b.center.y>3.8f&&b.center.y<4.82f;bool horiz=b.center.z>-4.6f&&b.center.z<-3.4f&&b.center.y>4.65f;bool pole=b.size.y>4&&b.size.z<.3f;bool arm=b.size.z>7&&b.size.y<2;
foreach(int i in part){var p=q*v[i];if(vert||horiz)p=Head(p,vert);else if(pole){p.x*=1.8f;p.z*=1.8f;}else if(arm)p+=(q*normals[i])*.04f;v[i]=inv*p;}}
mesh.vertices=v;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,meshpath);}
mf.sharedMesh=mesh;
var controller=go.GetComponent<CityTrafficSignal>()??go.AddComponent<CityTrafficSignal>();
for(int s=0;s<3;s++){string name=new[]{"Red","Yellow","Green"}[s];var color=new[]{new Color(1,.015f,.005f),new Color(1,.48f,.008f),new Color(.015f,1,.09f)}[s];string mp=Folder+name+" Glow.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(mp);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.name=name+" Glow";mat.SetColor("_BaseColor",color*3);mat.SetFloat("_Cull",0);mat.enableInstancing=true;AssetDatabase.CreateAsset(mat,mp);}
string lp=Folder+name+" Lenses.asset";var lens=AssetDatabase.LoadAssetAtPath<Mesh>(lp);if(!lens){var v=new List<Vector3>();var tris=new List<int>();for(int h=0;h<2;h++){var center=h==0?new Vector3(.196f,4.667f-s*.282f,-7.778f):new Vector3(.283f,4.837f,-4.277f+s*.282f);center=Head(center,h==0);int start=v.Count;v.Add(inv*center);for(int j=0;j<20;j++){float a=j*Mathf.PI*2/20;v.Add(inv*(center+new Vector3(0,Mathf.Cos(a),Mathf.Sin(a))*.128f));}for(int j=0;j<20;j++){tris.Add(start);tris.Add(start+1+j);tris.Add(start+1+(j+1)%20);}}lens=new Mesh{name=name+" Lenses"};lens.SetVertices(v);lens.SetTriangles(tris,0);lens.RecalculateNormals();lens.RecalculateBounds();AssetDatabase.CreateAsset(lens,lp);}
var child=go.transform.Find(name+" Light");if(!child){child=new GameObject(name+" Light").transform;child.SetParent(go.transform,false);child.gameObject.AddComponent<MeshFilter>();child.gameObject.AddComponent<MeshRenderer>();}child.GetComponent<MeshFilter>().sharedMesh=lens;var r=child.GetComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;if(s==0)controller.redLamp=child.gameObject;else if(s==1)controller.yellowLamp=child.gameObject;else controller.greenLamp=child.gameObject;
}
controller.Red();PrefabUtility.SaveAsPrefabAsset(go,path);AssetDatabase.SaveAssets();File.WriteAllText("VenueLightingReview/SignalReport.txt","Prefab updated. Pole 1.8x thickness; arm radius increased by 0.04m; signal heads 1.35x. Original texture and UVs preserved. Two lenses combined per color; 40 triangles and one additional draw call per active signal, zero realtime lights. Manual state has no Update loop. Auto cycle optional.");
}finally{PrefabUtility.UnloadPrefabContents(go);}
EditorApplication.delayCall+=Capture;
}
static void Capture(){var c=UnityEngine.Object.FindObjectOfType<CityDayNightController>(true);var r=UnityEngine.Object.FindObjectsOfType<CityTrafficSignal>().FirstOrDefault();if(!r)return;var b=r.GetComponent<Renderer>().bounds;var front=r.transform.rotation*Quaternion.Inverse(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Signal.prefab").transform.localRotation)*Vector3.right;var pos=b.center+front*11+Vector3.up*.5f;var pose=Tuple.Create(pos,Quaternion.LookRotation(b.center-pos));var old=r.state;foreach(var state in new[]{CityTrafficSignal.SignalState.Red,CityTrafficSignal.SignalState.Yellow,CityTrafficSignal.SignalState.Green,CityTrafficSignal.SignalState.Off}){r.SetState(state);CityLightingBuilder.Capture(c,pose,"Signal-"+state);}r.SetState(old);}
}
